using NovaCore.Core;
using NovaCore.Core.ReferenceFrames;
using System.Diagnostics;

var tests=new (string,Action)[]{("transform algebra",TransformAlgebra),("hierarchy and conversion",Hierarchy),("reference-frame graph",Graph),("reference-frame paths",PathQueries),("transform resolution",TransformResolution),("ORB",Orb),("CCI/CCF",CciCcf),("rotating velocity",Velocity),("validation",Validation)};
foreach(var (name,test) in tests){test();Console.WriteLine($"PASS {name}");}
Benchmark();

static void TransformAlgebra(){var t=new FrameTransform(new Double3(5,0,0),DoubleQuaternion.FromAxisAngle(Double3.UnitZ,Math.PI/2));var p=new Double3(1,0,0);Near(t.ParentToLocal(t.LocalToParent(p)),p);Near(Double3.Cross(Double3.UnitX,Double3.UnitY),Double3.UnitZ);}
static void Hierarchy(){var root=new ReferenceFrameId(1);var child=new ReferenceFrameId(2);var snap=new ReferenceFrameSnapshot([(new ReferenceFrameDefinition(root,null,ReferenceFrameKind.Ecl,"ECL"),CelestialFrameFactory.RootEcl()),(new ReferenceFrameDefinition(child,root,ReferenceFrameKind.Cce,"CCE"),CelestialFrameFactory.Cce(new Double3(4e12,0,0),Double3.Zero))]);var r=new ReferenceFrameResolver(snap);Check(r.TryResolvePosition(new FramePosition(child,new Double3(.25,0,0)),out var world),"resolve");Near(world.Value,new Double3(4e12+.25,0,0));Check(r.TryConvertPosition(new FramePosition(child,new Double3(.25,0,0)),root,out var converted),"convert");Near(converted.Value,world.Value);}
static void Graph(){var root=new ReferenceFrameId(1);var first=new ReferenceFrameId(2);var second=new ReferenceFrameId(3);var grandchild=new ReferenceFrameId(4);var builder=new ReferenceFrameGraphBuilder();builder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));builder.Add(new ReferenceFrameNode(first,root,ReferenceFrameKind.Cce,"first"));builder.Add(new ReferenceFrameNode(second,root,ReferenceFrameKind.Orb,"second"));builder.Add(new ReferenceFrameNode(grandchild,first,ReferenceFrameKind.Cci,"grandchild"));var graph=builder.Build();Check(graph.Count==4&&graph.RootCount==1&&graph.TryGetNode(second,out var node)&&node.DiagnosticName=="second","graph lookup");Check(graph.TryGetParent(grandchild,out var parent)&&parent.Id==first&&graph.IsAncestorOf(root,grandchild)&&graph.IsAncestorOf(first,grandchild)&&!graph.IsAncestorOf(grandchild,grandchild),"graph ancestry");var children="";foreach(var child in graph.GetChildren(root))children+=child.Id.Value+",";Check(children=="2,3,","graph child insertion order");var traversal="";foreach(var frame in graph.TraverseDepthFirst())traversal+=frame.Id.Value+",";Check(traversal=="1,2,4,3,","graph depth-first order");var ancestors="";foreach(var ancestor in graph.GetAncestors(grandchild))ancestors+=ancestor.Id.Value+",";Check(ancestors=="2,1,","graph parent-first ancestry order");Throws<ArgumentException>(()=>builder.Add(new ReferenceFrameNode(first,root,ReferenceFrameKind.Cce,"duplicate")));Throws<ArgumentException>(()=>new ReferenceFrameGraphBuilder().Add(new ReferenceFrameNode(first,root,ReferenceFrameKind.Cce,"missing parent")));var before=GC.GetAllocatedBytesForCurrentThread();for(var i=0;i<100_000;i++){foreach(var _ in graph.GetChildren(root)){}foreach(var _ in graph.TraverseDepthFirst()){}foreach(var _ in graph.GetAncestors(grandchild)){}_=graph.IsAncestorOf(root,grandchild);}_=graph.TryGetParent(grandchild,out _);Check(GC.GetAllocatedBytesForCurrentThread()==before,"graph traversal allocates zero bytes");}
static void PathQueries(){var root=new ReferenceFrameId(1);var left=new ReferenceFrameId(2);var right=new ReferenceFrameId(3);var leaf=new ReferenceFrameId(4);var builder=new ReferenceFrameGraphBuilder();builder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));builder.Add(new ReferenceFrameNode(left,root,ReferenceFrameKind.Cce,"left"));builder.Add(new ReferenceFrameNode(right,root,ReferenceFrameKind.Orb,"right"));builder.Add(new ReferenceFrameNode(leaf,left,ReferenceFrameKind.Cci,"leaf"));var graph=builder.Build();Check(ReferenceFramePathQuery.TryFindLowestCommonAncestor(graph,leaf,right,out var lca)&&lca==root,"path LCA siblings");Check(ReferenceFramePathQuery.TryFindLowestCommonAncestor(graph,left,leaf,out lca)&&lca==left,"path LCA ancestor");Span<ReferenceFrameId> path=stackalloc ReferenceFrameId[4];var rootPath=ReferenceFramePathQuery.TryBuildRootToNodePath(graph,leaf,path);Check(rootPath.Succeeded&&PathEquals(ReferenceFramePathQuery.EnumerateTransformPath(path,rootPath),1,2,4),"root path");var traversal=ReferenceFramePathQuery.TryBuildTraversalPath(graph,leaf,right,path);Check(traversal.Succeeded&&traversal.LowestCommonAncestor==root&&traversal.UpwardNodeCount==3&&PathEquals(ReferenceFramePathQuery.EnumerateTransformPath(path,traversal),4,2,1,3),"sibling traversal path");var ancestor=ReferenceFramePathQuery.TryBuildTraversalPath(graph,left,leaf,path);Check(ancestor.Succeeded&&PathEquals(ReferenceFramePathQuery.EnumerateTransformPath(path,ancestor),2,4),"descendant traversal path");Span<ReferenceFrameId> tooSmall=stackalloc ReferenceFrameId[2];Check(ReferenceFramePathQuery.TryBuildTraversalPath(graph,leaf,right,tooSmall).Status==ReferenceFramePathStatus.DestinationBufferTooSmall,"path buffer rejection");Check(ReferenceFramePathQuery.TryBuildTraversalPath(graph,new ReferenceFrameId(99),right,path).Status==ReferenceFramePathStatus.SourceUnknown,"path source rejection");var unrelatedBuilder=new ReferenceFrameGraphBuilder();var otherRoot=new ReferenceFrameId(10);unrelatedBuilder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));unrelatedBuilder.Add(new ReferenceFrameNode(otherRoot,null,ReferenceFrameKind.Ecl,"other"));var unrelated=unrelatedBuilder.Build();Check(ReferenceFramePathQuery.TryBuildTraversalPath(unrelated,root,otherRoot,path).Status==ReferenceFramePathStatus.UnrelatedFrames,"path unrelated rejection");var before=GC.GetAllocatedBytesForCurrentThread();for(var i=0;i<100_000;i++){var result=ReferenceFramePathQuery.TryBuildTraversalPath(graph,leaf,right,path);if(!result.Succeeded)throw new Exception("path allocation setup");_=ReferenceFramePathQuery.EnumerateTransformPath(path,result);_ = ReferenceFramePathQuery.TryFindLowestCommonAncestor(graph,leaf,right,out _);}Check(GC.GetAllocatedBytesForCurrentThread()==before,"path queries allocate zero bytes");}
static void TransformResolution(){var root=new ReferenceFrameId(1);var source=new ReferenceFrameId(2);var target=new ReferenceFrameId(3);var child=new ReferenceFrameId(4);var builder=new ReferenceFrameGraphBuilder();builder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));builder.Add(new ReferenceFrameNode(source,root,ReferenceFrameKind.Cce,"source"));builder.Add(new ReferenceFrameNode(target,root,ReferenceFrameKind.Orb,"target"));builder.Add(new ReferenceFrameNode(child,source,ReferenceFrameKind.Cci,"child"));var graph=builder.Build();var rotation=DoubleQuaternion.FromAxisAngle(Double3.UnitZ,Math.PI/2);var transforms=new ReferenceFrameTransformSet(graph,[new ReferenceFrameEvaluation(root,new EvaluatedReferenceFrame(FrameTransform.Identity,Double3.Zero,Double3.Zero,true)),new ReferenceFrameEvaluation(source,new EvaluatedReferenceFrame(new FrameTransform(new Double3(10,0,0),rotation),new Double3(1,0,0),Double3.UnitZ,false)),new ReferenceFrameEvaluation(target,new EvaluatedReferenceFrame(new FrameTransform(new Double3(0,20,0),DoubleQuaternion.Identity),Double3.Zero,Double3.Zero,true)),new ReferenceFrameEvaluation(child,new EvaluatedReferenceFrame(new FrameTransform(new Double3(0,2,0),DoubleQuaternion.Identity),Double3.Zero,Double3.Zero,true))]);Span<ReferenceFrameId> sourcePath=stackalloc ReferenceFrameId[8];Span<ReferenceFrameId> targetPath=stackalloc ReferenceFrameId[8];Span<ReferenceFrameId> traversalPath=stackalloc ReferenceFrameId[8];Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,root,root,sourcePath,targetPath,traversalPath,out var identity)==ReferenceFrameTransformResolutionStatus.Success&&identity==ResolvedReferenceFrameTransform.Identity,"transform identity");Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,source,root,sourcePath,targetPath,traversalPath,out var sourceToRoot)==ReferenceFrameTransformResolutionStatus.Success,"source root resolution");Near(sourceToRoot.ConvertPosition(new Double3(1,0,0)),new Double3(10,1,0));Near(sourceToRoot.ConvertDirection(Double3.UnitX),Double3.UnitY);Near(sourceToRoot.ConvertOrientation(DoubleQuaternion.Identity).Rotate(Double3.UnitX),Double3.UnitY);Near(sourceToRoot.ConvertVelocity(new Double3(3,0,0),Double3.Zero),new Double3(-2,0,0));Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,root,source,sourcePath,targetPath,traversalPath,out var rootToSource)==ReferenceFrameTransformResolutionStatus.Success,"root local resolution");Near(rootToSource.ConvertPosition(sourceToRoot.ConvertPosition(new Double3(3,4,0))),new Double3(3,4,0));Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,source,target,sourcePath,targetPath,traversalPath,out var sibling)==ReferenceFrameTransformResolutionStatus.Success,"sibling resolution");Near(sibling.ConvertPosition(Double3.Zero),new Double3(10,-20,0));var ancestorStatus=ReferenceFrameTransformResolver.TryResolveTransform(transforms,root,child,sourcePath,targetPath,traversalPath,out var ancestorToDescendant);var descendantStatus=ReferenceFrameTransformResolver.TryResolveTransform(transforms,child,root,sourcePath,targetPath,traversalPath,out var descendantToAncestor);Check(ancestorStatus==ReferenceFrameTransformResolutionStatus.Success&&descendantStatus==ReferenceFrameTransformResolutionStatus.Success,"ancestor descendant resolution");Near(descendantToAncestor.ConvertPosition(ancestorToDescendant.ConvertPosition(new Double3(7,8,0))),new Double3(7,8,0));Span<ReferenceFrameId> small=stackalloc ReferenceFrameId[1];Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,source,target,small,targetPath,traversalPath,out _)==ReferenceFrameTransformResolutionStatus.SourcePathBufferTooSmall,"source path buffer rejection");Check(ReferenceFrameTransformResolver.TryResolveTransform(transforms,new ReferenceFrameId(99),target,sourcePath,targetPath,traversalPath,out _)==ReferenceFrameTransformResolutionStatus.SourceUnknown&&ReferenceFrameTransformResolver.TryResolveTransform(transforms,source,new ReferenceFrameId(99),sourcePath,targetPath,traversalPath,out _)==ReferenceFrameTransformResolutionStatus.TargetUnknown,"transform unknown rejection");var unrelatedBuilder=new ReferenceFrameGraphBuilder();var otherRoot=new ReferenceFrameId(10);unrelatedBuilder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));unrelatedBuilder.Add(new ReferenceFrameNode(otherRoot,null,ReferenceFrameKind.Ecl,"other"));var unrelatedGraph=unrelatedBuilder.Build();var unrelatedSet=new ReferenceFrameTransformSet(unrelatedGraph,[new ReferenceFrameEvaluation(root,new EvaluatedReferenceFrame(FrameTransform.Identity,Double3.Zero,Double3.Zero,true)),new ReferenceFrameEvaluation(otherRoot,new EvaluatedReferenceFrame(FrameTransform.Identity,Double3.Zero,Double3.Zero,true))]);Check(ReferenceFrameTransformResolver.TryResolveTransform(unrelatedSet,root,otherRoot,sourcePath,targetPath,traversalPath,out _)==ReferenceFrameTransformResolutionStatus.UnrelatedFrames,"transform unrelated rejection");var deepBuilder=new ReferenceFrameGraphBuilder();var deepEvaluations=new ReferenceFrameEvaluation[9];for(var index=0;index<9;index++){var id=new ReferenceFrameId(index+20);deepBuilder.Add(new ReferenceFrameNode(id,index==0?null:new ReferenceFrameId(index+19),ReferenceFrameKind.Cce,$"deep{index}"));deepEvaluations[index]=new ReferenceFrameEvaluation(id,index==0?new EvaluatedReferenceFrame(FrameTransform.Identity,Double3.Zero,Double3.Zero,true):new EvaluatedReferenceFrame(new FrameTransform(new Double3(1,0,0),DoubleQuaternion.Identity),Double3.Zero,Double3.Zero,true));}var deepSet=new ReferenceFrameTransformSet(deepBuilder.Build(),deepEvaluations);Span<ReferenceFrameId> deepSource=stackalloc ReferenceFrameId[16];Span<ReferenceFrameId> deepTarget=stackalloc ReferenceFrameId[16];Span<ReferenceFrameId> deepTraversal=stackalloc ReferenceFrameId[16];Check(ReferenceFrameTransformResolver.TryResolveTransform(deepSet,new ReferenceFrameId(28),new ReferenceFrameId(20),deepSource,deepTarget,deepTraversal,out var deep)==ReferenceFrameTransformResolutionStatus.Success&&deep.ConvertPosition(Double3.Zero).X==8d,"deep transform resolution");var before=GC.GetAllocatedBytesForCurrentThread();for(var index=0;index<100_000;index++)if(ReferenceFrameTransformResolver.TryResolveTransform(transforms,source,target,sourcePath,targetPath,traversalPath,out _)!=ReferenceFrameTransformResolutionStatus.Success)throw new Exception("transform allocation setup");Check(GC.GetAllocatedBytesForCurrentThread()==before,"transform resolution allocates zero bytes");var hash=TransformResolutionHash();Check(TransformResolutionHash()==hash,"transform resolution deterministic hash");Console.WriteLine($"Deterministic transform-resolution hash: 0x{hash:X16}");}
static void Orb(){var q=new OrbitalFrameGeometry(0,0,0).ToEclRotation();Near(q.Rotate(Double3.UnitX),Double3.UnitX);Near(q.Rotate(Double3.UnitZ),Double3.UnitZ);var z=new OrbitalFrameGeometry(Math.PI/2,0,0).ToEclRotation().Rotate(Double3.UnitZ);Near(z,new Double3(0,-1,0));}
static void CciCcf(){var cci=CelestialFrameFactory.Cci(Double3.Zero,Double3.Zero,Double3.UnitZ,Double3.UnitX);Near(cci.LocalToParent.Rotation.Rotate(Double3.UnitZ),Double3.UnitZ);var ccf=CelestialFrameFactory.Ccf(Math.PI/2,1);Near(ccf.LocalToParent.Rotation.Rotate(Double3.UnitX),Double3.UnitY);try{CelestialFrameFactory.Cci(Double3.Zero,Double3.Zero,Double3.UnitZ,Double3.UnitZ);throw new Exception("degeneracy accepted");}catch(ArgumentException){}}
static void Velocity(){var root=new ReferenceFrameId(1);var rotating=new ReferenceFrameId(2);var s=new ReferenceFrameSnapshot([(new ReferenceFrameDefinition(root,null,ReferenceFrameKind.Ecl,"ECL"),CelestialFrameFactory.RootEcl()),(new ReferenceFrameDefinition(rotating,root,ReferenceFrameKind.Ccf,"CCF"),CelestialFrameFactory.Ccf(0,2))]);var r=new ReferenceFrameResolver(s);Check(r.TryConvertVelocity(new FramePosition(rotating,new Double3(3,0,0)),new FrameVelocity(rotating,Double3.Zero),root,out var v),"velocity");Near(v.Value,new Double3(0,6,0));}
static void Validation(){var root=new ReferenceFrameId(1);var child=new ReferenceFrameId(2);try{_ = new ReferenceFrameSnapshot([(new ReferenceFrameDefinition(root,child,ReferenceFrameKind.Ecl,"E"),CelestialFrameFactory.RootEcl()),(new ReferenceFrameDefinition(child,root,ReferenceFrameKind.Cce,"C"),CelestialFrameFactory.Cce(Double3.Zero,Double3.Zero))]);throw new Exception("cycle accepted");}catch(ArgumentException){}try{_ = new ReferenceFrameSnapshot([(new ReferenceFrameDefinition(root,null,ReferenceFrameKind.Cce,"bad"),CelestialFrameFactory.RootEcl())]);throw new Exception("bad root accepted");}catch(ArgumentException){}}
static void Near(Double3 a,Double3 b){if((a-b).LengthSquared>1e-18)throw new Exception($"Expected {b}, got {a}");}
static void Check(bool value,string text){if(!value)throw new Exception(text);}
static void Throws<T>(Action action) where T:Exception{try{action();throw new Exception($"Expected {typeof(T).Name}");}catch(T){}}
static bool PathEquals(ReadOnlySpan<ReferenceFrameId> path,params long[] values){if(path.Length!=values.Length)return false;for(var index=0;index<values.Length;index++)if(path[index].Value!=values[index])return false;return true;}
static ulong TransformResolutionHash(){var root=new ReferenceFrameId(50);var child=new ReferenceFrameId(51);var builder=new ReferenceFrameGraphBuilder();builder.Add(new ReferenceFrameNode(root,null,ReferenceFrameKind.Ecl,"root"));builder.Add(new ReferenceFrameNode(child,root,ReferenceFrameKind.Cce,"child"));var graph=builder.Build();var set=new ReferenceFrameTransformSet(graph,[new ReferenceFrameEvaluation(root,new EvaluatedReferenceFrame(FrameTransform.Identity,Double3.Zero,Double3.Zero,true)),new ReferenceFrameEvaluation(child,new EvaluatedReferenceFrame(new FrameTransform(new Double3(4e12,.25,-3),DoubleQuaternion.FromAxisAngle(Double3.UnitZ,.5d)),new Double3(1,2,3),new Double3(0,0,.25),false))]);Span<ReferenceFrameId> a=stackalloc ReferenceFrameId[4];Span<ReferenceFrameId> b=stackalloc ReferenceFrameId[4];Span<ReferenceFrameId> c=stackalloc ReferenceFrameId[4];ulong hash=14695981039346656037;for(var index=0;index<1024;index++){Check(ReferenceFrameTransformResolver.TryResolveTransform(set,child,root,a,b,c,out var resolved)==ReferenceFrameTransformResolutionStatus.Success,"transform hash resolve");var p=resolved.ConvertPosition(new Double3(index*.001,2,-1));var v=resolved.ConvertVelocity(new Double3(index*.001,2,-1),Double3.Zero);hash=MixFrame(hash,(ulong)BitConverter.DoubleToInt64Bits(p.X));hash=MixFrame(hash,(ulong)BitConverter.DoubleToInt64Bits(p.Y));hash=MixFrame(hash,(ulong)BitConverter.DoubleToInt64Bits(v.X));}return hash;}
static ulong MixFrame(ulong hash,ulong value)=>(hash^value)*1099511628211;
static void Benchmark(){var root=new ReferenceFrameId(1);var child=new ReferenceFrameId(2);var s=new ReferenceFrameSnapshot([(new ReferenceFrameDefinition(root,null,ReferenceFrameKind.Ecl,"ECL"),CelestialFrameFactory.RootEcl()),(new ReferenceFrameDefinition(child,root,ReferenceFrameKind.Cce,"CCE"),CelestialFrameFactory.Cce(new Double3(4e12,0,0),Double3.Zero))]);var r=new ReferenceFrameResolver(s);r.TryResolvePosition(new FramePosition(child,Double3.Zero),out _);var watch=new Stopwatch();var before=GC.GetAllocatedBytesForCurrentThread();watch.Start();UniversePosition p=default;for(var i=0;i<10000;i++)r.TryResolvePosition(new FramePosition(child,new Double3(i*.001,0,0)),out p);watch.Stop();var allocated=GC.GetAllocatedBytesForCurrentThread()-before;Console.WriteLine($"Benchmark: 10,000 root resolutions in {watch.Elapsed.TotalMilliseconds:F3} ms; managed allocations={allocated} bytes; final={p.Value.X:R}");Check(allocated==0,"resolver allocated during repeated resolution");}
